// Quick test script for Malmö Live scraper
import axios from 'axios';

const MALMO_LIVE_API = 'https://malmolive.se/api/events';

async function testMalmolive() {
  console.log('[test] Fetching from Malmö Live API...');

  const response = await axios.get(MALMO_LIVE_API, {
    headers: {
      'User-Agent': 'EventPulse/1.0',
      'Accept': 'application/json',
    },
    timeout: 30000,
  });

  console.log(`[test] Status: ${response.status}`);
  console.log(`[test] Events received: ${response.data.length}`);

  // Show first event as sample
  if (response.data.length > 0) {
    const event = response.data[0];
    console.log('\n[tets] Sample event:');
    console.log(`  Title: ${event.title}`);
    console.log(`  Date: ${event.field_date_time}`);
    console.log(`  Venue: ${event.field_venue}`);
    console.log(`  Price: ${event.price_low} - ${event.price_high} SEK`);
    console.log(`  Tessitura ID: ${event.tessitura_instance_id}`);
    console.log(`  URL: https://malmolive.se${event.view_node}`);
  }
}

testMalmolive().catch(console.error);
EOF
node test_malmolive.mjs

